args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel WHERE {
  VALUES ?film { dbr:The_Boy_on_the_Galloping_Horse dbr:Claretta }
  ?film dbo:director ?director .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = 'en') }
}

SELECT ?director ?directorLabel ?birthDate1 ?birthDate2 WHERE {
  VALUES ?director { dbr:Adam_Guziński dbr:Pasquale_Squitieri }
  OPTIONAL { ?director dbo:birthDate ?birthDate1. }
  OPTIONAL { ?director dbp:birthDate ?birthDate2. }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel)='en') }
}

SELECT ?film ?filmLabel ?director ?directorBirthDate WHERE {
  VALUES ?film { dbr:The_Boy_on_the_Galloping_Horse dbr:Claretta }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1. }
  OPTIONAL { ?director dbp:birthDate ?bd2. }
  BIND(COALESCE(?bd1, ?bd2) AS ?directorBirthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
}
ORDER BY ?directorBirthDate
LIMIT 1

