PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?film ?filmLabel ?director ?directorBirthDate WHERE {
  VALUES ?film {
    dbr:The_Boy_on_the_Galloping_Horse dbr:Claretta
  }
  ?film dbo:director ?director .
  OPTIONAL {
    ?director dbo:birthDate ?bd1 .
  }
  OPTIONAL {
    ?director dbp:birthDate ?bd2 .
  }
  BIND(COALESCE(?bd1 , ?bd2) AS ?directorBirthDate)
  OPTIONAL {
    ?film rdfs:label ?filmLabel
    FILTER(lang(?filmLabel) = 'en')
  }
}
ORDER BY ?directorBirthDate
LIMIT 1

